def build():
    n = NB()
    n.md("""# CortexHR chatbot: the complete data-science workflow for a classification problem
Every numbered item of the supplied workflow (1-37) is a section below, with a **coverage table** followed by real code and outputs on the CortexHR chatbot data (33 intents, multiclass text classification). It is the Phase 2 counterpart of `06_complete_classification_workflow.ipynb`.
**Rules kept throughout:** the 132-message test set is untouched until Section 37; all learned preprocessing is fitted on training rows only; the validation vault is never used.""")
    n.code(SETUP)
    n.code("""from sklearn.base import clone
from sklearn.metrics import accuracy_score
def clean(s): return re.sub(r'\\s+', ' ', str(s)).strip()
train = H.load('chatbot_nlu_training'); test = H.load('chatbot_test_set')
Xtr, ytr = train.text.map(clean).tolist(), train.intent.astype(str).tolist(); Xte, yte = test.text.map(clean).tolist(), test.expected_intent.astype(str).tolist()
prod = CB.train_intent_model(CSV / 'chatbot_nlu_training.csv')
print(len(Xtr), 'training |', len(Xte), 'sealed test')""")
    for ph, (pname, secs) in PHASES.items():
        n.md(f"---\n# PHASE {ph}: {pname}")
        for s in secs:
            title, how, code = S37[s]
            n.md(f"---\n## {s}. {title}\n\n| Requirement | How it is covered in this notebook |\n|---|---|\n| {title} | {how} |")
            n.code(code)
    n.md("### Evidence for your report\nSection 37 held-out accuracy and the confusion pairs; Section 29 threshold table.\n**You can now say:** *I ran the complete 37-step classification workflow on a 33-intent text problem and reported the result honestly.*")
    return n.save("P2_MASTER_37_chatbot_classification_workflow.ipynb")
